"use client";

import { useMemo, useState } from "react";
import Image from "next/image";
import { addDays, endOfMonth, endOfQuarter, endOfYear, format, startOfMonth, startOfQuarter, startOfYear, subDays } from "date-fns";
import { Bar, BarChart, CartesianGrid, Legend, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { AlertTriangle, ArrowDownToLine, BadgeCheck, BadgePercent, Banknote, Building2, ChartNoAxesCombined, Check, ChevronDown, CircleDollarSign, ClipboardList, Copy, Download, ExternalLink, FileCheck2, Filter, HandCoins, Landmark, Link2, Loader2, Plus, QrCode, RefreshCw, Rocket, Search, ShieldAlert, ShieldCheck, Sparkles, UsersRound, Video, WalletCards, X } from "lucide-react";
import { cn, formatMoney } from "@/lib/utils";
import type { XgroupDashboardData, XgroupSection } from "@/lib/xgroup-types";

const STATUS_LABELS: Record<string, string> = {
  PENDING_DUE_DILIGENCE: "Chờ thẩm định",
  ACTIVE: "Đang hoạt động",
  PAUSED: "Tạm dừng",
  SUSPENDED: "Khóa",
  DRAFT: "Bản nháp",
  ARCHIVED: "Lưu trữ",
  NEW: "Mới",
  CONTACTED: "Đã liên hệ",
  QUALIFIED: "Đủ điều kiện",
  QUOTED: "Đã báo giá",
  AWAITING_DEPOSIT: "Chờ cọc",
  SCHEDULED: "Đã xếp lịch",
  IN_SERVICE: "Đang triển khai",
  WON: "Thành công",
  LOST: "Không thành công",
  PENDING: "Chờ dịch vụ",
  READY: "Chờ duyệt",
  APPROVED: "Đã duyệt chi",
  PAID: "Đã chi",
  ON_HOLD: "Tạm giữ",
  VOID: "Đã hủy",
};

const PIPELINE_STAGES = ["NEW", "CONTACTED", "QUALIFIED", "QUOTED", "AWAITING_DEPOSIT", "SCHEDULED", "IN_SERVICE", "WON", "LOST"];

function compactMoney(value: number) {
  if (Math.abs(value) >= 1_000_000_000) return `${(value / 1_000_000_000).toLocaleString("vi-VN", { maximumFractionDigits: 2 })} tỷ`;
  if (Math.abs(value) >= 1_000_000) return `${(value / 1_000_000).toLocaleString("vi-VN", { maximumFractionDigits: 1 })} triệu`;
  return formatMoney(value);
}

function statusTone(status: string) {
  if (["ACTIVE", "WON", "PAID", "COMPLETED"].includes(status)) return "bg-[#f1e5dd] text-[#76551d] ring-[#e8d2c4]";
  if (["READY", "APPROVED", "QUALIFIED", "SCHEDULED"].includes(status)) return "bg-[#e8f1fb] text-[#245581] ring-[#bed4e8]";
  if (["SUSPENDED", "LOST", "VOID"].includes(status)) return "bg-[#fae9e9] text-[#a22b31] ring-[#efc5c7]";
  return "bg-[#fff4da] text-[#805f18] ring-[#e8d39e]";
}

function StatusPill({ status }: { status: string }) {
  return <span className={cn("inline-flex shrink-0 items-center rounded-full px-2 py-1 text-[9px] font-bold ring-1", statusTone(status))}>{STATUS_LABELS[status] ?? status}</span>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "green" }: { label: string; value: string; detail: string; icon: React.ComponentType<{ size?: number }>; tone?: "green" | "gold" | "blue" | "red" }) {
  const tones = { green: "from-[#4c191b] to-[#76551d] text-white", gold: "from-[#7a5519] to-[#b8872a] text-white", blue: "from-[#244b68] to-[#34749b] text-white", red: "from-[#5b2527] to-[#9f3439] text-white" };
  return <article className={cn("min-h-[112px] rounded-2xl bg-gradient-to-br p-3.5 shadow-sm", tones[tone])}><div className="flex items-start justify-between gap-2"><p className="text-[9px] font-bold uppercase tracking-[0.13em] text-white/68">{label}</p><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-white/10"><Icon size={14} /></span></div><strong className="mt-2 block text-xl tracking-tight">{value}</strong><p className="mt-1 text-[9px] leading-4 text-white/65">{detail}</p></article>;
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="flex items-start justify-between gap-3"><div><p className="text-[9px] font-bold uppercase tracking-[0.16em] text-[#a85f29]">{eyebrow}</p><h2 className="mt-1 text-lg font-semibold tracking-tight">{title}</h2><p className="mt-1 max-w-3xl text-[10px] leading-5 text-[#687975]">{description}</p></div>{action}</div>;
}

type CreateMode = "district" | "affiliate" | "asset" | "lead" | null;
type AllocationItem = XgroupDashboardData["events"][number]["allocations"][number];

export function XgroupDashboardClient({ initialData, activeSection }: { initialData: XgroupDashboardData; activeSection: XgroupSection }) {
  const [data, setData] = useState(initialData);
  const [from, setFrom] = useState(initialData.range.from);
  const [to, setTo] = useState(initialData.range.to);
  const [districtId, setDistrictId] = useState(initialData.scope.districtId ?? "all");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [query, setQuery] = useState("");
  const [expandedEvent, setExpandedEvent] = useState<string | null>(null);
  const [createMode, setCreateMode] = useState<CreateMode>(null);
  const [actionAllocation, setActionAllocation] = useState<{ item: AllocationItem; status: "APPROVED" | "PAID" | "ON_HOLD" | "VOID" } | null>(null);
  const [busy, setBusy] = useState("");
  const [copied, setCopied] = useState("");

  const visibleEvents = useMemo(() => {
    const keyword = query.trim().toLocaleLowerCase("vi-VN");
    return keyword ? data.events.filter((item) => `${item.companyName} ${item.eventCode} ${item.districtName} ${item.affiliateName}`.toLocaleLowerCase("vi-VN").includes(keyword)) : data.events;
  }, [data.events, query]);

  async function reload(next: { from?: string; to?: string; districtId?: string } = {}) {
    const nextFrom = next.from ?? from;
    const nextTo = next.to ?? to;
    const nextDistrict = next.districtId ?? districtId;
    setLoading(true);
    setError("");
    try {
      const params = new URLSearchParams({ from: nextFrom, to: nextTo, districtId: nextDistrict });
      const response = await fetch(`/api/xgroup/summary?${params}`, { cache: "no-store" });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.error ?? "Không thể tải báo cáo Xgroup.");
      setData(payload);
      setFrom(nextFrom);
      setTo(nextTo);
      setDistrictId(nextDistrict);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Không thể tải báo cáo Xgroup.");
    } finally {
      setLoading(false);
    }
  }

  function preset(key: "7d" | "month" | "quarter" | "year") {
    const now = new Date();
    const next = key === "7d" ? { from: format(subDays(now, 6), "yyyy-MM-dd"), to: format(now, "yyyy-MM-dd") } : key === "month" ? { from: format(startOfMonth(now), "yyyy-MM-dd"), to: format(endOfMonth(now), "yyyy-MM-dd") } : key === "quarter" ? { from: format(startOfQuarter(now), "yyyy-MM-dd"), to: format(endOfQuarter(now), "yyyy-MM-dd") } : { from: format(startOfYear(now), "yyyy-MM-dd"), to: format(endOfYear(now), "yyyy-MM-dd") };
    void reload(next);
  }

  async function mutate(url: string, method: "POST" | "PATCH", body: unknown, busyKey: string) {
    setBusy(busyKey);
    setError("");
    try {
      const response = await fetch(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error ?? "Không thể cập nhật dữ liệu.");
      await reload();
      return true;
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Không thể cập nhật dữ liệu.");
      return false;
    } finally {
      setBusy("");
    }
  }

  async function copy(value: string, key: string) {
    await navigator.clipboard.writeText(`${window.location.origin}${value}`);
    setCopied(key);
    window.setTimeout(() => setCopied(""), 1500);
  }

  function exportCsv() {
    const rows = [["Mã sự kiện", "Doanh nghiệp", "Thời gian", "Quận", "Affiliate", "Nguồn", "GMV", "Đã thu", "Còn phải thu", "Trạng thái"], ...data.events.map((item) => [item.eventCode, item.companyName, item.startsAt, item.districtName, item.affiliateName, item.sourceLabel, item.gmv, item.paidAmount, item.receivable, item.status])];
    const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")).join("\n");
    const url = URL.createObjectURL(new Blob([`\ufeff${csv}`], { type: "text/csv;charset=utf-8" }));
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `xgroup-business-${from}-${to}.csv`;
    anchor.click();
    URL.revokeObjectURL(url);
  }

  const filterBar = (
    <section className="rounded-2xl border border-[#f1e5dd] bg-white p-3 shadow-sm">
      <div className="flex flex-wrap items-center gap-2">
        <span className="inline-flex items-center gap-1.5 text-[10px] font-bold text-[#76551d]"><Filter size={13} className="text-[#a85f29]" /> Phạm vi báo cáo</span>
        <div className="flex rounded-lg bg-[#fbf2e7] p-0.5">{([['7d', '7 ngày'], ['month', 'Tháng'], ['quarter', 'Quý'], ['year', 'Năm']] as const).map(([key, label]) => <button key={key} type="button" onClick={() => preset(key)} className="rounded-md px-2.5 py-1.5 text-[9px] font-semibold text-[#53635f] hover:bg-white">{label}</button>)}</div>
        <label className="flex items-center gap-1.5 rounded-lg border border-[#f1e5dd] px-2 py-1.5"><span className="text-[8px] text-[#7b8986]">Từ</span><input type="date" value={from} onChange={(event) => setFrom(event.target.value)} className="bg-transparent text-[9px] font-semibold outline-none" /></label>
        <label className="flex items-center gap-1.5 rounded-lg border border-[#f1e5dd] px-2 py-1.5"><span className="text-[8px] text-[#7b8986]">Đến</span><input type="date" value={to} onChange={(event) => setTo(event.target.value)} className="bg-transparent text-[9px] font-semibold outline-none" /></label>
        {data.scope.canManageAllDistricts ? <select value={districtId} onChange={(event) => { setDistrictId(event.target.value); void reload({ districtId: event.target.value }); }} className="min-h-8 rounded-lg border border-[#f1e5dd] bg-white px-2 text-[9px] font-semibold outline-none"><option value="all">Tất cả địa bàn</option>{data.districts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select> : <span className="rounded-lg bg-[#fbf2e7] px-2.5 py-2 text-[9px] font-semibold text-[#76551d]">{data.scope.districtLabel}</span>}
        <button type="button" onClick={() => void reload()} disabled={loading} className="ml-auto inline-flex h-8 items-center gap-1.5 rounded-lg bg-[#4c191b] px-3 text-[9px] font-semibold text-white disabled:opacity-60">{loading ? <Loader2 size={12} className="animate-spin" /> : <RefreshCw size={12} />} Cập nhật</button>
      </div>
      {error ? <p role="alert" className="mt-2 rounded-lg bg-[#fae9e9] px-3 py-2 text-[10px] font-semibold text-[#a22b31]">{error}</p> : null}
    </section>
  );

  const overview = <>
    <section className="overflow-hidden rounded-3xl bg-[radial-gradient(circle_at_top_right,rgba(216,182,93,.24),transparent_35%),linear-gradient(135deg,#281b18,#4c191b_52%,#76551d)] p-4 text-white shadow-lg sm:p-5">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div className="max-w-2xl"><p className="flex items-center gap-1.5 text-[9px] font-bold uppercase tracking-[0.18em] text-[#e9ca74]"><ShieldCheck size={13} /> Xgroup Super Control · Financial Intelligence</p><h1 className="mt-2 text-2xl font-semibold tracking-tight">Toàn cảnh Tâm An Business</h1><p className="mt-2 text-[11px] leading-5 text-white/68">Một nguồn sự thật từ cơ hội bán hàng, cọc, triển khai, GMV đến phân bổ 65%/35%. Tip của khách dành cho KTV được theo dõi riêng và tuyệt đối không nhập vào GMV.</p></div><div className="grid grid-cols-2 gap-2 text-center"><div className="rounded-xl bg-white/8 px-3 py-2 ring-1 ring-white/10"><strong className="block text-lg">{data.finance.targetProgress}%</strong><small className="text-[8px] text-white/60">Tiến độ mục tiêu kỳ</small></div><div className="rounded-xl bg-white/8 px-3 py-2 ring-1 ring-white/10"><strong className="block text-lg">{data.quality.attributionCoveragePercent}%</strong><small className="text-[8px] text-white/60">Dữ liệu có nguồn</small></div></div></div>
    </section>
    <div className="mt-3 grid grid-cols-2 gap-2 lg:grid-cols-4"><MetricCard label="GMV đã ghi nhận" value={compactMoney(data.finance.recognizedGmv)} detail={`${data.finance.completedCount}/${data.finance.eventCount} sự kiện hoàn tất`} icon={ChartNoAxesCombined} /><MetricCard label="Dòng tiền đã thu" value={compactMoney(data.finance.collected)} detail={`Còn phải thu ${compactMoney(data.finance.receivable)}`} icon={Landmark} tone="blue" /><MetricCard label="Doanh thu Xgroup 20%" value={compactMoney(data.finance.allocation.xgroupPlatform)} detail="Chỉ tính GMV dịch vụ đã hoàn tất" icon={CircleDollarSign} tone="gold" /><MetricCard label="Đội triển khai 65%" value={compactMoney(data.finance.allocation.deliveryTeamAmount)} detail="60% KTV · 5% trưởng đoàn" icon={UsersRound} tone="red" /></div>
    <div className="mt-3 grid gap-3 xl:grid-cols-[1.4fr_.6fr]"><section className="rounded-2xl border border-[#f1e5dd] bg-white p-3.5"><SectionHeading eyebrow="Dòng tiền theo thời gian" title="GMV, đã thu và phần Xgroup" description="Biến động được lấy từ các hồ sơ Business trong kỳ lọc; không cộng Tip KTV." /><div className="mt-3 h-[250px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.series} margin={{ left: -20, right: 4 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1e5dd" /><XAxis dataKey="label" tick={{ fontSize: 9, fill: "#74827f" }} axisLine={false} tickLine={false} /><YAxis tickFormatter={(value) => compactMoney(Number(value))} tick={{ fontSize: 8, fill: "#74827f" }} axisLine={false} tickLine={false} /><Tooltip formatter={(value) => formatMoney(Number(value))} contentStyle={{ borderRadius: 12, borderColor: "#f1e5dd", fontSize: 10 }} /><Legend wrapperStyle={{ fontSize: 9 }} /><Bar name="GMV" dataKey="gmv" fill="#76551d" radius={[5, 5, 0, 0]} /><Bar name="Đã thu" dataKey="collected" fill="#d2a640" radius={[5, 5, 0, 0]} /><Bar name="Xgroup 20%" dataKey="xgroup" fill="#387aa0" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer></div></section><section className="rounded-2xl border border-[#f1e5dd] bg-white p-3.5"><SectionHeading eyebrow="Kỷ luật dữ liệu" title="Điểm cần xử lý" description="Cảnh báo ảnh hưởng trực tiếp đến đối soát và trách nhiệm phân phối." /><div className="mt-3 space-y-2">{[{ icon: Link2, label: "Sự kiện chưa đủ nguồn/địa bàn", value: data.quality.unassignedEventCount, detail: compactMoney(data.quality.unassignedGmv), alert: data.quality.unassignedEventCount > 0 }, { icon: ShieldAlert, label: "Affiliate chờ công bố lợi ích", value: data.quality.pendingComplianceCount, detail: "Tránh xung đột lợi ích", alert: data.quality.pendingComplianceCount > 0 }, { icon: FileCheck2, label: "Khoản phân bổ quá hạn", value: data.quality.overdueAllocationCount, detail: "Cần duyệt hoặc khóa lý do", alert: data.quality.overdueAllocationCount > 0 }].map(({ icon: Icon, label, value, detail, alert }) => <div key={label} className={cn("flex items-center gap-2 rounded-xl p-3 ring-1", alert ? "bg-[#fff7e6] ring-[#ead7a5]" : "bg-[#fbf2e7] ring-[#e8d2c4]")}><span className={cn("flex h-9 w-9 items-center justify-center rounded-xl", alert ? "bg-white text-[#936b17]" : "bg-white text-[#76551d]")}><Icon size={16} /></span><span className="min-w-0 flex-1"><strong className="block text-[10px]">{label}</strong><small className="text-[8px] text-[#667a73]">{detail}</small></span><b className="text-lg">{value}</b></div>)}</div></section></div>
    <section className="mt-3 rounded-2xl border border-[#f1e5dd] bg-white p-3.5"><SectionHeading eyebrow="Phễu bán hàng cấp Quận" title="Cơ hội cần hành động tiếp theo" description="Trưởng phòng Quận nhìn ngay người phụ trách, nguồn giới thiệu, giá trị dự kiến và bước kế tiếp." action={<button type="button" onClick={() => setCreateMode("lead")} className="inline-flex shrink-0 items-center gap-1 rounded-lg bg-[#4c191b] px-3 py-2 text-[9px] font-semibold text-white"><Plus size={12} /> Cơ hội</button>} /><LeadList data={data} mutate={mutate} busy={busy} limit={6} /></section>
  </>;

  const finance = <>
    <SectionHeading eyebrow="Business Financial Control" title="Báo cáo tài chính Tâm An Business" description="GMV, công nợ và phân bổ được khóa theo từng sự kiện. 65% thuộc đội trực tiếp triển khai; 35% thuộc nền tảng và mạng lưới phân phối." action={<button type="button" onClick={exportCsv} className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-[#d2ad5d] bg-white px-3 py-2 text-[9px] font-semibold text-[#76551d]"><ArrowDownToLine size={13} /> Xuất CSV</button>} />
    <div className="mt-3 grid grid-cols-2 gap-2 lg:grid-cols-5"><MetricCard label="GMV đã đặt" value={compactMoney(data.finance.bookedGmv)} detail={`${data.finance.eventCount} hồ sơ trong kỳ`} icon={Rocket} /><MetricCard label="GMV hoàn tất" value={compactMoney(data.finance.recognizedGmv)} detail="Cơ sở tính phân bổ" icon={BadgeCheck} tone="blue" /><MetricCard label="Đã thu" value={compactMoney(data.finance.collected)} detail={`Cọc ${compactMoney(data.finance.depositCollected)}`} icon={Banknote} tone="gold" /><MetricCard label="Còn phải thu" value={compactMoney(data.finance.receivable)} detail="Cần đối soát theo Bill" icon={WalletCards} tone="red" /><MetricCard label="Tip ngoài GMV" value={compactMoney(data.finance.tipExcluded)} detail="Không đưa vào Bill/GMV" icon={Sparkles} tone="green" /></div>
    <section className="mt-3 rounded-2xl border border-[#f1e5dd] bg-white p-4"><SectionHeading eyebrow="Waterfall phân bổ" title="100% GMV Business đã hoàn tất" description="Tỷ lệ cố định theo mô hình kinh doanh đã duyệt; mọi khoản chi chỉ chuyển trạng thái sau khi có đối soát." /><div className="mt-4 overflow-hidden rounded-xl"><div className="flex h-10 text-center text-[8px] font-bold text-white"><div className="flex w-[60%] items-center justify-center bg-[#76551d]">KTV 60%</div><div className="flex w-[5%] min-w-10 items-center justify-center bg-[#a85f29]">5%</div><div className="flex w-[20%] items-center justify-center bg-[#b98926]">Xgroup 20%</div><div className="flex w-[5%] min-w-10 items-center justify-center bg-[#4f78a1]">5%</div><div className="flex w-[10%] items-center justify-center bg-[#9f3439]">Affiliate 10%</div></div></div><div className="mt-3 grid grid-cols-2 gap-2 lg:grid-cols-5">{[{ label: "KTV trực tiếp", rate: "60%", value: data.finance.allocation.ktvDirect }, { label: "KTV trưởng đoàn", rate: "5%", value: data.finance.allocation.teamLeader }, { label: "Nền tảng Xgroup", rate: "20%", value: data.finance.allocation.xgroupPlatform }, { label: "Giám đốc Quận", rate: "5%", value: data.finance.allocation.districtDirector }, { label: "Affiliate trực tiếp", rate: "10%", value: data.finance.allocation.directAffiliate }].map((item) => <div key={item.label} className="rounded-xl bg-[#fbf2e7] p-3 text-center ring-1 ring-[#f1e5dd]"><span className="text-[8px] font-bold text-[#667a73]">{item.rate}</span><strong className="mt-1 block text-sm">{compactMoney(item.value)}</strong><small className="mt-1 block text-[8px] text-[#687975]">{item.label}</small></div>)}</div></section>
    <EventTable events={visibleEvents} query={query} setQuery={setQuery} expandedEvent={expandedEvent} setExpandedEvent={setExpandedEvent} />
  </>;

  const districts = <>
    <SectionHeading eyebrow="Territory Performance" title="Điều hành Kinh doanh cấp Quận" description="Mỗi Trưởng phòng Quận chỉ nhìn và vận hành địa bàn được cấp; Xgroup so sánh mục tiêu, GMV, phễu và năng lực Affiliate giữa các Quận." action={data.scope.canManageAllDistricts ? <button type="button" onClick={() => setCreateMode("district")} className="inline-flex shrink-0 items-center gap-1 rounded-lg bg-[#4c191b] px-3 py-2 text-[9px] font-semibold text-white"><Plus size={12} /> Thêm Quận</button> : null} />
    <div className="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{data.districts.map((item) => <article key={item.id} className="rounded-2xl border border-[#f1e5dd] bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-2"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#fbf2e7] text-[#76551d]"><Building2 size={18} /></span><span className="rounded-full bg-[#fbf2e7] px-2 py-1 text-[8px] font-bold text-[#5f706c]">{item.code}</span></div><h3 className="mt-3 text-base font-semibold">{item.name}</h3><p className="mt-1 text-[9px] text-[#667a73]">{item.managerName} · {item.city}</p><div className="mt-3 flex items-end justify-between"><div><small className="text-[8px] uppercase text-[#7b8986]">GMV kỳ lọc</small><strong className="block text-lg text-[#76551d]">{compactMoney(item.gmv)}</strong></div><b className="text-sm">{item.progress}%</b></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[#f1e5dd]"><div className="h-full rounded-full bg-gradient-to-r from-[#76551d] to-[#d2a640]" style={{ width: `${Math.min(100, item.progress)}%` }} /></div><div className="mt-3 grid grid-cols-4 gap-1 text-center">{[[item.leadCount, "Lead"], [item.eventCount, "Đoàn"], [item.activeAffiliateCount, "Affiliate"], [`${item.conversionRate}%`, "Chốt"]].map(([value, label]) => <div key={label} className="rounded-lg bg-[#fbf2e7] px-1 py-2"><strong className="block text-[11px]">{value}</strong><small className="text-[7px] text-[#667a73]">{label}</small></div>)}</div><p className="mt-3 rounded-lg bg-[#fff7e4] px-2.5 py-2 text-[8px] text-[#76591a]">Mục tiêu năm: <strong>{compactMoney(item.annualTarget)}</strong> · Đã thu kỳ này: <strong>{compactMoney(item.collected)}</strong></p></article>)}</div>
    <section className="mt-3 rounded-2xl border border-[#f1e5dd] bg-white p-3.5"><SectionHeading eyebrow="Sales pipeline" title="Cơ hội theo địa bàn" description="Cập nhật giai đoạn ngay tại đây để Xgroup và Trưởng phòng không phải theo dõi bằng bảng ngoài." action={<button type="button" onClick={() => setCreateMode("lead")} className="inline-flex shrink-0 items-center gap-1 rounded-lg bg-[#4c191b] px-3 py-2 text-[9px] font-semibold text-white"><Plus size={12} /> Thêm lead</button>} /><LeadList data={data} mutate={mutate} busy={busy} /></section>
  </>;

  const affiliate = <>
    <SectionHeading eyebrow="Direct Affiliate Governance" title="Mạng lưới người giới thiệu trực tiếp" description="Một tầng trực tiếp hưởng 10% GMV hợp lệ. Hồ sơ CEO, kế toán, mua hàng, HR, quản lý tòa nhà hoặc đối tác đều phải có nguồn và công bố lợi ích khi cần." action={<button type="button" onClick={() => setCreateMode("affiliate")} className="inline-flex shrink-0 items-center gap-1 rounded-lg bg-[#4c191b] px-3 py-2 text-[9px] font-semibold text-white"><Plus size={12} /> Affiliate</button>} />
    <div className="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{data.affiliates.map((item) => <article key={item.id} className="rounded-2xl border border-[#f1e5dd] bg-white p-4 shadow-sm"><div className="flex items-start gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#fff3e0] text-[#956515]"><BadgePercent size={18} /></span><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><h3 className="truncate text-sm font-semibold">{item.displayName}</h3><p className="mt-0.5 truncate text-[8px] text-[#667a73]">{item.organization ?? item.profile} · {item.districtName}</p></div><StatusPill status={item.status} /></div></div></div><div className="mt-3 grid grid-cols-3 gap-1 text-center">{[[item.clickCount, "Click"], [item.leadCount, "Lead"], [`${item.conversionRate}%`, "Chốt"]].map(([value, label]) => <div key={label} className="rounded-lg bg-[#fbf2e7] p-2"><strong className="block text-xs">{value}</strong><small className="text-[7px] text-[#667a73]">{label}</small></div>)}</div><div className="mt-3 grid grid-cols-2 gap-2"><div className="rounded-lg bg-[#fbf2e7] p-2"><small className="text-[7px] text-[#61746f]">GMV hoàn tất</small><strong className="mt-0.5 block text-[11px] text-[#76551d]">{compactMoney(item.gmv)}</strong></div><div className="rounded-lg bg-[#fff4da] p-2"><small className="text-[7px] text-[#76591a]">Hoa hồng 10%</small><strong className="mt-0.5 block text-[11px] text-[#805f18]">{compactMoney(item.commission)}</strong></div></div><div className={cn("mt-3 rounded-lg px-2.5 py-2 text-[8px] leading-4", item.conflictDisclosureRequired && !item.conflictDisclosureAccepted ? "bg-[#fae9e9] text-[#9a2f34]" : "bg-[#fbf2e7] text-[#a85f29]")}>{item.conflictDisclosureRequired ? item.conflictDisclosureAccepted ? "Đã công bố và lưu chấp thuận về lợi ích giới thiệu." : "Cần hoàn tất công bố lợi ích trước khi kích hoạt/chi trả." : "Không phát hiện yêu cầu công bố lợi ích đặc biệt."}</div><div className="mt-3 flex items-center justify-between"><code className="rounded bg-[#fbf2e7] px-2 py-1 text-[8px] font-bold">{item.code}</code><span className="text-[8px] text-[#667a73]">{item.assetCount} tài sản nguồn</span></div></article>)}</div>
  </>;

  const assets = <>
    <SectionHeading eyebrow="Affiliate Content Operations" title="Kho Link · QR · Video có truy vết" description="Mỗi tài sản có mã nguồn riêng, số lượt mở, lead, chuyển đổi và GMV. QR không trỏ thẳng tới nội dung mơ hồ mà đi qua link đo lường an toàn." action={<button type="button" onClick={() => setCreateMode("asset")} className="inline-flex shrink-0 items-center gap-1 rounded-lg bg-[#4c191b] px-3 py-2 text-[9px] font-semibold text-white"><Plus size={12} /> Tạo tài sản</button>} />
    <div className="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{data.assets.map((item) => <article key={item.id} className="overflow-hidden rounded-2xl border border-[#f1e5dd] bg-white shadow-sm"><div className="flex items-start gap-3 p-4"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#fbf2e7] text-[#76551d]">{item.type === "QR" ? <QrCode size={18} /> : item.type === "VIDEO" ? <Video size={18} /> : <Link2 size={18} />}</span><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><h3 className="text-sm font-semibold leading-5">{item.title}</h3><StatusPill status={item.status} /></div><p className="mt-1 text-[8px] text-[#667a73]">{item.districtName} · {item.affiliateName}</p></div></div>{item.type === "QR" ? <div className="mx-4 flex items-center gap-3 rounded-xl bg-[#fbf2e7] p-3"><Image unoptimized width={80} height={80} src={`/api/xgroup/assets/${encodeURIComponent(item.id)}/qr`} alt={`QR ${item.title}`} className="h-20 w-20 rounded-lg bg-white p-1 ring-1 ring-[#f1e5dd]" /><div className="min-w-0"><p className="text-[8px] font-semibold leading-4 text-[#53635f]">QR có định danh nguồn; tải để in hoặc gửi trực tiếp.</p><a href={`/api/xgroup/assets/${encodeURIComponent(item.id)}/qr`} download={`${item.code}.png`} className="mt-2 inline-flex items-center gap-1 rounded-lg bg-[#4c191b] px-2.5 py-1.5 text-[8px] font-semibold text-white"><Download size={10} /> Tải QR</a></div></div> : item.type === "VIDEO" && item.videoUrl ? <a href={item.videoUrl} target="_blank" rel="noreferrer" className="mx-4 flex items-center justify-between rounded-xl bg-[#eef4f8] p-3 text-[9px] font-semibold text-[#285a78]"><span className="inline-flex items-center gap-1.5"><Video size={13} /> Mở video nội dung</span><ExternalLink size={12} /></a> : null}<div className="p-4"><div className="grid grid-cols-4 gap-1 text-center">{[[item.clickCount, "Mở"], [item.leadCount, "Lead"], [item.completedCount, "Chốt"], [`${item.conversionRate}%`, "CVR"]].map(([value, label]) => <div key={label} className="rounded-lg bg-[#fbf2e7] p-2"><strong className="block text-[10px]">{value}</strong><small className="text-[7px] text-[#667a73]">{label}</small></div>)}</div><p className="mt-3 text-[8px] text-[#667a73]">GMV quy thuộc: <strong className="text-[#76551d]">{compactMoney(item.gmv)}</strong></p><div className="mt-2 flex items-center gap-2"><code className="min-w-0 flex-1 truncate rounded-lg bg-[#fbf2e7] px-2 py-2 text-[8px]">{item.trackingPath}</code><button type="button" onClick={() => void copy(item.trackingPath, item.id)} className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#4c191b] text-white" aria-label="Sao chép link">{copied === item.id ? <Check size={12} /> : <Copy size={12} />}</button><a href={item.trackingPath} target="_blank" className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-[#f1e5dd] text-[#76551d]" aria-label="Mở link"><ExternalLink size={12} /></a></div></div></article>)}</div>
  </>;

  const reconciliation = <>
    <SectionHeading eyebrow="Settlement & Audit" title="Đối soát phân bổ theo từng sự kiện" description="Chỉ khoản đã hoàn tất dịch vụ mới chuyển sang Chờ duyệt. Xgroup phê duyệt trước, sau đó mới xác nhận Đã chi kèm mã giao dịch ngân hàng." action={<button type="button" onClick={exportCsv} className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-[#d2ad5d] bg-white px-3 py-2 text-[9px] font-semibold text-[#76551d]"><ArrowDownToLine size={13} /> Xuất dữ liệu</button>} />
    <div className="mt-3 grid grid-cols-2 gap-2 lg:grid-cols-4"><MetricCard label="Cơ sở đối soát" value={compactMoney(data.finance.recognizedGmv)} detail="GMV đã hoàn tất" icon={FileCheck2} /><MetricCard label="Đội triển khai 65%" value={compactMoney(data.finance.allocation.deliveryTeamAmount)} detail="KTV + trưởng đoàn" icon={UsersRound} tone="blue" /><MetricCard label="Phân phối 15%" value={compactMoney(data.finance.allocation.districtDirector + data.finance.allocation.directAffiliate)} detail="Quận + Affiliate trực tiếp" icon={HandCoins} tone="gold" /><MetricCard label="Quá hạn" value={String(data.quality.overdueAllocationCount)} detail="Khoản cần hành động" icon={AlertTriangle} tone="red" /></div>
    <section className="mt-3 overflow-hidden rounded-2xl border border-[#f1e5dd] bg-white"><div className="flex flex-col gap-2 border-b border-[#f1e5dd] p-3 sm:flex-row sm:items-center"><label className="flex min-w-0 flex-1 items-center gap-2 rounded-lg bg-[#fbf2e7] px-3 py-2"><Search size={13} className="text-[#a85f29]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Tìm công ty, mã, Quận hoặc Affiliate" className="min-w-0 flex-1 bg-transparent text-[10px] outline-none" /></label><span className="text-[9px] text-[#667a73]">{visibleEvents.length} sự kiện</span></div><div className="divide-y divide-[#f1e5dd]">{visibleEvents.map((event) => { const open = expandedEvent === event.id; return <article key={event.id}><button type="button" onClick={() => setExpandedEvent(open ? null : event.id)} className="flex w-full items-start gap-3 p-3 text-left"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#fbf2e7] text-[#76551d]"><Building2 size={15} /></span><span className="min-w-0 flex-1"><span className="flex flex-wrap items-center gap-1.5"><strong className="text-[11px]">{event.companyName}</strong><span className="rounded-full bg-[#fbf2e7] px-2 py-0.5 text-[8px]">{event.status}</span></span><small className="mt-1 block text-[8px] text-[#667a73]">{event.districtName} · {event.affiliateName} · {event.sourceLabel}</small></span><span className="shrink-0 text-right"><strong className="block text-[11px]">{compactMoney(event.gmv)}</strong><small className="text-[8px] text-[#667a73]">Còn {compactMoney(event.receivable)}</small></span><ChevronDown size={14} className={cn("mt-1 transition", open && "rotate-180")} /></button>{open ? <div className="border-t border-[#f1e5dd] bg-[#fffaf6] p-3"><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-5">{event.allocations.map((item) => <div key={item.id} className="rounded-xl border border-[#f1e5dd] bg-white p-3"><div className="flex items-start justify-between gap-2"><span className="text-[8px] font-bold text-[#657570]">{item.rateBps / 100}% · {item.label}</span><StatusPill status={item.status} /></div><strong className="mt-2 block text-sm">{formatMoney(item.amount)}</strong><p className="mt-1 min-h-8 text-[8px] leading-4 text-[#667a73]">{item.beneficiaryLabel}</p>{item.bankReference ? <p className="mt-1 truncate rounded bg-[#fbf2e7] px-2 py-1 text-[7px] text-[#76551d]">GD: {item.bankReference}</p> : null}{data.scope.canApprovePayouts ? <div className="mt-2 grid grid-cols-2 gap-1">{item.status === "READY" ? <button type="button" onClick={() => setActionAllocation({ item, status: "APPROVED" })} className="col-span-2 rounded-lg bg-[#76551d] px-2 py-1.5 text-[8px] font-semibold text-white">Phê duyệt</button> : null}{item.status === "APPROVED" ? <button type="button" onClick={() => setActionAllocation({ item, status: "PAID" })} className="col-span-2 rounded-lg bg-[#b4872d] px-2 py-1.5 text-[8px] font-semibold text-white">Xác nhận đã chi</button> : null}{!["PAID", "VOID"].includes(item.status) ? <><button type="button" onClick={() => setActionAllocation({ item, status: "ON_HOLD" })} className="rounded-lg border border-[#ddc785] px-2 py-1.5 text-[7px] font-semibold text-[#805f18]">Tạm giữ</button><button type="button" onClick={() => setActionAllocation({ item, status: "VOID" })} className="rounded-lg border border-[#e0bfc1] px-2 py-1.5 text-[7px] font-semibold text-[#9a2f34]">Hủy</button></> : null}</div> : <p className="mt-2 text-[7px] text-[#667a73]">Quyền duyệt thuộc Xgroup Super Admin.</p>}</div>)}</div></div> : null}</article>; })}</div></section>
  </>;

  const sectionContent = activeSection === "finance" ? finance : activeSection === "districts" ? districts : activeSection === "affiliates" ? affiliate : activeSection === "assets" ? assets : activeSection === "reconciliation" ? reconciliation : overview;

  return <div className="mx-auto max-w-[1480px] px-3 py-3 sm:px-5 sm:py-4">{filterBar}<div className="mt-3">{sectionContent}</div>{createMode ? <CreateDialog mode={createMode} data={data} busy={busy} onClose={() => setCreateMode(null)} onSubmit={async (url, body, key) => { const ok = await mutate(url, "POST", body, key); if (ok) setCreateMode(null); }} /> : null}{actionAllocation ? <AllocationDialog action={actionAllocation} busy={busy} onClose={() => setActionAllocation(null)} onSubmit={async (body) => { const ok = await mutate("/api/xgroup/allocations", "PATCH", body, `allocation:${actionAllocation.item.id}`); if (ok) setActionAllocation(null); }} /> : null}</div>;
}

function LeadList({ data, mutate, busy, limit }: { data: XgroupDashboardData; mutate: (url: string, method: "POST" | "PATCH", body: unknown, busyKey: string) => Promise<boolean>; busy: string; limit?: number }) {
  const rows = limit ? data.leads.slice(0, limit) : data.leads;
  return <div className="mt-3 grid gap-2 lg:grid-cols-2">{rows.map((lead) => <article key={lead.id} className="flex items-start gap-3 rounded-xl border border-[#f1e5dd] bg-[#fffaf6] p-3"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-white text-[#76551d] ring-1 ring-[#f1e5dd]"><ClipboardList size={15} /></span><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><strong className="block text-[10px]">{lead.companyName}</strong><small className="mt-0.5 block text-[8px] text-[#667a73]">{lead.districtName} · {lead.affiliateName}</small></div><select value={lead.stage} disabled={busy === `lead:${lead.id}`} onChange={(event) => void mutate("/api/xgroup/leads", "PATCH", { id: lead.id, stage: event.target.value, ...(event.target.value === "LOST" ? { lostReason: "Không tiếp tục sau cập nhật của phụ trách" } : {}) }, `lead:${lead.id}`)} className="max-w-[116px] rounded-lg border border-[#f1e5dd] bg-white px-2 py-1 text-[8px] font-semibold outline-none">{PIPELINE_STAGES.map((stage) => <option key={stage} value={stage}>{STATUS_LABELS[stage]}</option>)}</select></div><div className="mt-2 flex flex-wrap items-center gap-1.5 text-[8px]"><span className="rounded bg-[#fbf2e7] px-2 py-1 font-semibold text-[#76551d]">{compactMoney(lead.estimatedGmv)}</span><span className="rounded bg-[#fbf2e7] px-2 py-1 text-[#657570]">{lead.sourceLabel}</span></div>{lead.nextAction ? <p className="mt-2 text-[8px] leading-4 text-[#657570]"><strong>Bước tiếp:</strong> {lead.nextAction}{lead.nextActionAt ? ` · ${new Date(lead.nextActionAt).toLocaleDateString("vi-VN")}` : ""}</p> : null}</div></article>)}{!rows.length ? <p className="rounded-xl bg-[#fbf2e7] p-8 text-center text-[10px] text-[#667a73] lg:col-span-2">Chưa có cơ hội trong phạm vi này.</p> : null}</div>;
}

function EventTable({ events, query, setQuery, expandedEvent, setExpandedEvent }: { events: XgroupDashboardData["events"]; query: string; setQuery: (value: string) => void; expandedEvent: string | null; setExpandedEvent: (value: string | null) => void }) {
  return <section className="mt-3 overflow-hidden rounded-2xl border border-[#f1e5dd] bg-white"><div className="flex flex-col gap-2 border-b border-[#f1e5dd] p-3 sm:flex-row sm:items-center"><label className="flex min-w-0 flex-1 items-center gap-2 rounded-lg bg-[#fbf2e7] px-3 py-2"><Search size={13} className="text-[#a85f29]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Tìm hồ sơ Business" className="min-w-0 flex-1 bg-transparent text-[10px] outline-none" /></label><span className="text-[9px] text-[#667a73]">{events.length} hồ sơ</span></div><div className="divide-y divide-[#f1e5dd]">{events.map((event) => <article key={event.id}><button type="button" onClick={() => setExpandedEvent(expandedEvent === event.id ? null : event.id)} className="grid w-full grid-cols-[minmax(0,1fr)_90px_18px] items-center gap-2 p-3 text-left sm:grid-cols-[minmax(0,1fr)_120px_110px_18px]"><span className="min-w-0"><strong className="block truncate text-[10px]">{event.companyName}</strong><small className="mt-0.5 block truncate text-[8px] text-[#667a73]">{event.eventCode} · {event.districtName} · {event.affiliateName}</small></span><span className="text-right"><strong className="block text-[10px]">{compactMoney(event.gmv)}</strong><small className="text-[7px] text-[#667a73]">GMV</small></span><span className="hidden text-right sm:block"><strong className={cn("block text-[10px]", event.receivable ? "text-[#a22b31]" : "text-[#76551d]")}>{compactMoney(event.receivable)}</strong><small className="text-[7px] text-[#667a73]">Còn phải thu</small></span><ChevronDown size={13} className={cn("transition", expandedEvent === event.id && "rotate-180")} /></button>{expandedEvent === event.id ? <div className="border-t border-[#f1e5dd] bg-[#fffaf6] p-3"><div className="grid gap-2 sm:grid-cols-3"><p className="rounded-lg bg-white p-2 text-[8px]"><strong>Nguồn</strong><span className="mt-1 block text-[#667a73]">{event.sourceLabel}</span></p><p className="rounded-lg bg-white p-2 text-[8px]"><strong>Địa điểm</strong><span className="mt-1 block text-[#667a73]">{event.location}</span></p><p className="rounded-lg bg-white p-2 text-[8px]"><strong>Thời gian</strong><span className="mt-1 block text-[#667a73]">{new Date(event.startsAt).toLocaleString("vi-VN")}</span></p></div></div> : null}</article>)}{!events.length ? <p className="p-10 text-center text-xs text-[#667a73]">Không có hồ sơ phù hợp.</p> : null}</div></section>;
}

function DialogFrame({ title, subtitle, onClose, children }: { title: string; subtitle: string; onClose: () => void; children: React.ReactNode }) {
  return <div className="fixed inset-0 z-50 overflow-y-auto bg-[#281b18]/70 p-3 backdrop-blur-sm"><div className="mx-auto my-4 max-w-lg overflow-hidden rounded-2xl bg-white shadow-2xl"><div className="flex items-start justify-between gap-3 bg-gradient-to-br from-[#281b18] to-[#76551d] p-4 text-white"><div><p className="text-[9px] font-bold uppercase tracking-[0.14em] text-[#e9ca74]">Xgroup Business</p><h2 className="mt-1 text-lg font-semibold">{title}</h2><p className="mt-1 text-[9px] leading-4 text-white/65">{subtitle}</p></div><button type="button" onClick={onClose} className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-white/10"><X size={16} /></button></div>{children}</div></div>;
}

function CreateDialog({ mode, data, busy, onClose, onSubmit }: { mode: Exclude<CreateMode, null>; data: XgroupDashboardData; busy: string; onClose: () => void; onSubmit: (url: string, body: unknown, key: string) => Promise<void> }) {
  const defaultDistrict = data.scope.districtId ?? data.districts[0]?.id ?? "";
  const titles = { district: ["Thiết lập địa bàn mới", "Gán mục tiêu GMV và Trưởng phòng phụ trách."], affiliate: ["Tạo hồ sơ Affiliate", "Một tầng trực tiếp, hoa hồng cố định 10% GMV hợp lệ."], asset: ["Tạo Link · QR · Video", "Tài sản có mã nguồn riêng để đo Click, Lead, chuyển đổi và GMV."], lead: ["Tạo cơ hội Business", "Ghi nhận cơ hội tại Quận trước khi phát sinh hồ sơ đặt dịch vụ."] } as const;
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    if (mode === "district") return onSubmit("/api/xgroup/districts", { code: form.get("code"), name: form.get("name"), city: form.get("city"), annualGmvTarget: Number(form.get("annualGmvTarget")), managerUserId: form.get("managerUserId") || null }, "create:district");
    if (mode === "affiliate") return onSubmit("/api/xgroup/affiliates", { code: form.get("code"), districtId: form.get("districtId"), displayName: form.get("displayName"), organization: form.get("organization") || null, title: form.get("title") || null, phone: form.get("phone") || null, email: form.get("email") || null, referrerProfile: form.get("referrerProfile"), conflictDisclosureRequired: form.get("conflictDisclosureRequired") === "on", conflictDisclosureAccepted: form.get("conflictDisclosureAccepted") === "on", complianceNote: form.get("complianceNote") || null, status: data.scope.canApprovePayouts ? "ACTIVE" : "PENDING_DUE_DILIGENCE" }, "create:affiliate");
    if (mode === "asset") return onSubmit("/api/xgroup/assets", { code: form.get("code"), districtId: form.get("districtId"), affiliateId: form.get("affiliateId") || null, type: form.get("type"), title: form.get("title"), destinationPath: form.get("destinationPath"), videoUrl: form.get("videoUrl") || null, status: form.get("status") }, "create:asset");
    return onSubmit("/api/xgroup/leads", { leadCode: form.get("leadCode"), districtId: form.get("districtId"), affiliateId: form.get("affiliateId") || null, companyName: form.get("companyName"), contactName: form.get("contactName") || null, contactPhone: form.get("contactPhone") || null, contactEmail: form.get("contactEmail") || null, officeAddress: form.get("officeAddress") || null, estimatedGmv: Number(form.get("estimatedGmv")), nextAction: form.get("nextAction") || null, nextActionAt: form.get("nextActionAt") ? new Date(String(form.get("nextActionAt"))).toISOString() : null, note: form.get("note") || null }, "create:lead");
  }
  const inputClass = "mt-1.5 w-full rounded-xl border border-[#f1e5dd] bg-white px-3 py-2.5 text-[11px] outline-none focus:border-[#a85f29]";
  const labelClass = "block text-[9px] font-bold text-[#53635f]";
  return <DialogFrame title={titles[mode][0]} subtitle={titles[mode][1]} onClose={onClose}><form onSubmit={submit} className="grid gap-3 p-4 sm:grid-cols-2">{mode === "district" ? <><label className={labelClass}>Mã địa bàn<input required name="code" placeholder="CAU_GIAY" className={inputClass} /></label><label className={labelClass}>Tên địa bàn<input required name="name" placeholder="Quận Cầu Giấy" className={inputClass} /></label><label className={labelClass}>Thành phố<input required name="city" defaultValue="Hà Nội" className={inputClass} /></label><label className={labelClass}>Mục tiêu GMV năm<input required name="annualGmvTarget" type="number" min="0" defaultValue="8700000000" className={inputClass} /></label><label className={cn(labelClass, "sm:col-span-2")}>Trưởng phòng phụ trách<select name="managerUserId" className={inputClass}><option value="">Chưa bổ nhiệm</option>{data.managers.filter((item) => !item.districtId).map((item) => <option key={item.id} value={item.id}>{item.name} · {item.username}</option>)}</select></label></> : null}{mode === "affiliate" ? <><label className={labelClass}>Mã Affiliate<input required name="code" placeholder="CEO-CG-001" className={inputClass} /></label><label className={labelClass}>Địa bàn<select required name="districtId" defaultValue={defaultDistrict} className={inputClass}>{data.districts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className={labelClass}>Họ tên<input required name="displayName" className={inputClass} /></label><label className={labelClass}>Tổ chức<input name="organization" className={inputClass} /></label><label className={labelClass}>Chức danh<input name="title" placeholder="CEO / Kế toán / Mua hàng..." className={inputClass} /></label><label className={labelClass}>Nhóm người giới thiệu<input required name="referrerProfile" placeholder="Đầu mối trực tiếp tại doanh nghiệp" className={inputClass} /></label><label className={labelClass}>Số điện thoại<input name="phone" className={inputClass} /></label><label className={labelClass}>Email<input name="email" type="email" className={inputClass} /></label><label className={cn(labelClass, "sm:col-span-2")}>Ghi chú tuân thủ<textarea name="complianceNote" rows={2} className={inputClass} /></label><label className="flex items-start gap-2 rounded-xl bg-[#fff7e4] p-3 text-[9px]"><input name="conflictDisclosureRequired" type="checkbox" /> Người giới thiệu đồng thời tham gia quyết định mua</label><label className="flex items-start gap-2 rounded-xl bg-[#fbf2e7] p-3 text-[9px]"><input name="conflictDisclosureAccepted" type="checkbox" /> Đã lưu chấp thuận/công bố lợi ích</label></> : null}{mode === "asset" ? <><label className={labelClass}>Mã nguồn<input required name="code" placeholder="QR-CG-CEO01" className={inputClass} /></label><label className={labelClass}>Loại<select name="type" className={inputClass}><option value="LINK">Link</option><option value="QR">QR</option><option value="VIDEO">Video</option></select></label><label className={labelClass}>Địa bàn<select required name="districtId" defaultValue={defaultDistrict} className={inputClass}>{data.districts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className={labelClass}>Affiliate<select name="affiliateId" className={inputClass}><option value="">Nguồn Xgroup/Quận</option>{data.affiliates.map((item) => <option key={item.id} value={item.id}>{item.displayName}</option>)}</select></label><label className={cn(labelClass, "sm:col-span-2")}>Tên tài sản<input required name="title" placeholder="QR giới thiệu dịch vụ Business buổi trưa" className={inputClass} /></label><label className={labelClass}>Trang đích<input required name="destinationPath" defaultValue="/doanh-nghiep" className={inputClass} /></label><label className={labelClass}>URL video HTTPS<input name="videoUrl" type="url" placeholder="https://..." className={inputClass} /></label><label className={cn(labelClass, "sm:col-span-2")}>Trạng thái<select name="status" defaultValue="ACTIVE" className={inputClass}><option value="DRAFT">Bản nháp</option><option value="ACTIVE">Kích hoạt</option><option value="PAUSED">Tạm dừng</option></select></label></> : null}{mode === "lead" ? <><label className={labelClass}>Mã cơ hội<input required name="leadCode" defaultValue={`LEAD-${data.generatedAt.replace(/\D/g, "").slice(-6)}`} className={inputClass} /></label><label className={labelClass}>Địa bàn<select required name="districtId" defaultValue={defaultDistrict} className={inputClass}>{data.districts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className={cn(labelClass, "sm:col-span-2")}>Doanh nghiệp<input required name="companyName" className={inputClass} /></label><label className={labelClass}>Người liên hệ<input name="contactName" className={inputClass} /></label><label className={labelClass}>Điện thoại<input name="contactPhone" className={inputClass} /></label><label className={labelClass}>Email<input name="contactEmail" type="email" className={inputClass} /></label><label className={labelClass}>Affiliate<select name="affiliateId" className={inputClass}><option value="">Nguồn trực tiếp</option>{data.affiliates.map((item) => <option key={item.id} value={item.id}>{item.displayName}</option>)}</select></label><label className={cn(labelClass, "sm:col-span-2")}>Địa chỉ<input name="officeAddress" className={inputClass} /></label><label className={labelClass}>GMV dự kiến<input required name="estimatedGmv" type="number" min="0" defaultValue="50000000" className={inputClass} /></label><label className={labelClass}>Hẹn hành động<input name="nextActionAt" type="datetime-local" defaultValue={format(addDays(new Date(data.generatedAt), 1), "yyyy-MM-dd'T'09:00")} className={inputClass} /></label><label className={cn(labelClass, "sm:col-span-2")}>Bước tiếp theo<input name="nextAction" defaultValue="Liên hệ xác nhận nhu cầu và lịch khảo sát" className={inputClass} /></label><label className={cn(labelClass, "sm:col-span-2")}>Ghi chú<textarea name="note" rows={2} className={inputClass} /></label></> : null}<div className="grid grid-cols-2 gap-2 border-t border-[#f1e5dd] pt-3 sm:col-span-2"><button type="button" onClick={onClose} className="rounded-xl border border-[#f1e5dd] px-4 py-2.5 text-[10px] font-semibold">Hủy</button><button type="submit" disabled={Boolean(busy)} className="inline-flex items-center justify-center gap-1.5 rounded-xl bg-[#4c191b] px-4 py-2.5 text-[10px] font-semibold text-white disabled:opacity-50">{busy ? <Loader2 size={12} className="animate-spin" /> : <Check size={12} />} Ghi nhận</button></div></form></DialogFrame>;
}

function AllocationDialog({ action, busy, onClose, onSubmit }: { action: { item: AllocationItem; status: "APPROVED" | "PAID" | "ON_HOLD" | "VOID" }; busy: string; onClose: () => void; onSubmit: (body: unknown) => Promise<void> }) {
  const title = action.status === "APPROVED" ? "Phê duyệt khoản phân bổ" : action.status === "PAID" ? "Xác nhận đã chi" : action.status === "ON_HOLD" ? "Tạm giữ đối soát" : "Hủy khoản phân bổ";
  return <DialogFrame title={title} subtitle={`${action.item.label} · ${action.item.beneficiaryLabel} · ${formatMoney(action.item.amount)}`} onClose={onClose}><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); void onSubmit({ id: action.item.id, status: action.status, bankReference: form.get("bankReference") || null, note: form.get("note") || null }); }} className="p-4"><div className="rounded-xl bg-[#fbf2e7] p-3 text-[10px] leading-5"><p><strong>Tỷ lệ:</strong> {action.item.rateBps / 100}%</p><p><strong>Số tiền:</strong> {formatMoney(action.item.amount)}</p><p><strong>Đối tượng:</strong> {action.item.beneficiaryLabel}</p></div>{action.status === "PAID" ? <label className="mt-3 block text-[9px] font-bold text-[#53635f]">Mã giao dịch ngân hàng<input required name="bankReference" className="mt-1.5 w-full rounded-xl border border-[#f1e5dd] px-3 py-2.5 text-[11px] outline-none" placeholder="Bắt buộc và không trùng" /></label> : null}<label className="mt-3 block text-[9px] font-bold text-[#53635f]">Ghi chú kiểm soát<textarea name="note" required={action.status === "ON_HOLD" || action.status === "VOID"} rows={3} className="mt-1.5 w-full rounded-xl border border-[#f1e5dd] px-3 py-2.5 text-[11px] outline-none" /></label><div className="mt-4 grid grid-cols-2 gap-2"><button type="button" onClick={onClose} className="rounded-xl border border-[#f1e5dd] px-4 py-2.5 text-[10px] font-semibold">Quay lại</button><button type="submit" disabled={Boolean(busy)} className="inline-flex items-center justify-center gap-1.5 rounded-xl bg-[#4c191b] px-4 py-2.5 text-[10px] font-semibold text-white disabled:opacity-50">{busy ? <Loader2 size={12} className="animate-spin" /> : <FileCheck2 size={12} />} Xác nhận</button></div></form></DialogFrame>;
}
